template.code:
cls, attr = choice([("Compte", "solde"), ("Personnage", "vie"), ("Reservoir", "niveau"), ("Joueur", "score")])
depart = randint(10, 50)
a, b = randint(2, 9), randint(2, 9)
m1, m2 = {"Compte": ("deposer", "retirer"), "Personnage": ("soigner", "blesser"),
          "Reservoir": ("remplir", "vider"), "Joueur": ("gagner", "perdre")}[cls]
o1, o2 = sample(["x", "y", "p", "q", "obj", "u", "v"], 2)
src = dedent(f'''
class {cls}:
    def __init__(self, {attr}):
        self.{attr} = {attr}

    def {m1}(self, n):
        self.{attr} = self.{attr} + n

    def {m2}(self, n):
        if n <= self.{attr}:
            self.{attr} = self.{attr} - n

{o1} = {cls}({depart})
{o2} = {o1}
{o1}.{m1}({a})
{o2}.{m2}({choice([b, depart + 100])})
print({o1}.{attr})
''')
out = run(src)
